def choose_move(observation):
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))
    res = observation.get("resources", []) or []
    obs = observation.get("obstacles", []) or []
    if isinstance(res, dict):
        res = list(res.values())
    if isinstance(obs, dict):
        obs = list(obs.values())

    def pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        if isinstance(v, dict):
            for a, b in (("x", "y"), ("col", "row"), ("c", "r"), ("row", "col")):
                if a in v and b in v:
                    return v[a], v[b]
        return None

    resources = []
    for r in res:
        p = pos(r)
        if p is not None:
            resources.append(p)
    obstacles = set()
    for o in obs:
        p = pos(o)
        if p is not None:
            obstacles.add(p)
    occupied = set(obstacles)
    pp = observation.get("self_path")
    if isinstance(pp, list):
        for p in pp:
            q = pos(p)
            if q is not None:
                occupied.add(q)
    pp = observation.get("opponent_path")
    if isinstance(pp, list):
        for p in pp:
            q = pos(p)
            if q is not None:
                occupied.add(q)

    if resources:
        tx, ty = min(resources, key=lambda p: abs(p[0] - sx) + abs(p[1] - sy))
    else:
        tx, ty = (w - 1 - ox, h - 1 - oy) if w and h else (sx, sy)

    best = (0, 0)
    best_score = -10**9
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            nx, ny = sx + dx, sy + dy
            if w and h and not (0 <= nx < w and 0 <= ny < h):
                continue
            if (nx, ny) in occupied:
                continue
            d = abs(nx - tx) + abs(ny - ty)
            od = abs(nx - ox) + abs(ny - oy)
            score = -d * 10 + od
            if dx == 0 and dy == 0:
                score -= 1
            if score > best_score:
                best_score = score
                best = (dx, dy)
    return [int(best[0]), int(best[1])]

